function initThaiAddressSelector(provId, distId, subId, zipId) {
    const provEl = document.getElementById(provId);
    const distEl = document.getElementById(distId);
    const subEl = document.getElementById(subId);
    const zipEl = document.getElementById(zipId);

    if (!provEl || !distEl || !subEl || !zipEl) return;

    // 1. Populate All 77 Provinces
    provEl.innerHTML = '<option value="">-- เลือกจังหวัด (77 จังหวัด) --</option>';
    THAI_ALL_77_PROVINCES.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.name;
        opt.textContent = p.name;
        provEl.appendChild(opt);
    });

    // On Province Change
    provEl.addEventListener('change', function () {
        const selectedProv = this.value;
        distEl.innerHTML = '<option value="">-- เลือกอำเภอ / เขต --</option>';
        subEl.innerHTML = '<option value="">-- เลือกตำบล / แขวง --</option>';
        zipEl.value = '';

        validateInput(provEl);

        const provData = THAI_ALL_77_PROVINCES.find(p => p.name === selectedProv);
        if (provData && provData.districts.length > 0) {
            distEl.disabled = false;
            provData.districts.forEach(d => {
                const opt = document.createElement('option');
                opt.value = d.name;
                opt.textContent = d.name;
                distEl.appendChild(opt);
            });
        } else if (selectedProv) {
            distEl.disabled = false;
            distEl.innerHTML = '<option value="เมือง">เมือง / อ.เมือง</option><option value="ทั่วไป">อำเภอทั่วไป</option>';
            subEl.disabled = false;
            subEl.innerHTML = '<option value="ทั่วไป">ตำบลทั่วไป</option>';
        } else {
            distEl.disabled = true;
            subEl.disabled = true;
        }
    });

    // On District Change
    distEl.addEventListener('change', function () {
        const selectedProv = provEl.value;
        const selectedDist = this.value;
        subEl.innerHTML = '<option value="">-- เลือกตำบล / แขวง --</option>';
        zipEl.value = '';

        validateInput(distEl);

        const provData = THAI_ALL_77_PROVINCES.find(p => p.name === selectedProv);
        if (provData) {
            const distData = provData.districts.find(d => d.name === selectedDist);
            if (distData && distData.subdistricts.length > 0) {
                subEl.disabled = false;
                distData.subdistricts.forEach(s => {
                    const opt = document.createElement('option');
                    opt.value = s.name;
                    opt.textContent = s.name;
                    opt.dataset.zip = s.zipcode;
                    subEl.appendChild(opt);
                });
            } else {
                subEl.disabled = false;
                subEl.innerHTML = '<option value="ทั่วไป">ตำบลทั่วไป</option>';
            }
        }
    });

    // On Sub-district Change
    subEl.addEventListener('change', function () {
        validateInput(subEl);
        const selectedOpt = this.options[this.selectedIndex];
        if (selectedOpt && selectedOpt.dataset.zip) {
            zipEl.value = selectedOpt.dataset.zip;
            validateInput(zipEl);
        }
    });

    zipEl.addEventListener('input', function () {
        validateInput(zipEl);
    });
}

// Inline Form Validation Engine with Visual Feedback
function validateInput(inputEl) {
    if (!inputEl) return true;

    const val = inputEl.value.trim();
    const type = inputEl.type;
    const name = inputEl.name || inputEl.id;
    let isValid = true;
    let errorMsg = '';

    if (inputEl.hasAttribute('required') && !val) {
        isValid = false;
        errorMsg = 'กรุณากรอกข้อมูลในช่องนี้';
    } else if (val) {
        if (type === 'email' || name.includes('email')) {
            const emailReg = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailReg.test(val)) {
                isValid = false;
                errorMsg = 'รูปแบบอีเมลไม่ถูกต้อง (เช่น example@domain.com)';
            }
        } else if (name.includes('phone') || name.includes('tel')) {
            const phoneReg = /^[0-9\-\s]{9,12}$/;
            if (!phoneReg.test(val)) {
                isValid = false;
                errorMsg = 'กรุณาระบุเบอร์โทรศัพท์ 9-10 หลัก (เช่น 0812345678)';
            }
        } else if (name.includes('zip') || idMatch(inputEl, 'zip')) {
            const zipReg = /^[0-9]{5}$/;
            if (!zipReg.test(val)) {
                isValid = false;
                errorMsg = 'รหัสไปรษณีย์ต้องเป็นตัวเลข 5 หลัก';
            }
        }
    }

    // Apply UI Feedback Styles
    const feedbackEl = getOrCreateFeedbackEl(inputEl);

    if (isValid) {
        inputEl.classList.remove('border-red-500', 'focus:ring-red-500', 'bg-red-50/20');
        inputEl.classList.add('border-emerald-500', 'focus:ring-emerald-500', 'bg-emerald-50/20');
        feedbackEl.innerHTML = '';
    } else {
        inputEl.classList.remove('border-emerald-500', 'focus:ring-emerald-500', 'bg-emerald-50/20');
        inputEl.classList.add('border-red-500', 'focus:ring-red-500', 'bg-red-50/20');
        feedbackEl.innerHTML = `<span class="text-red-500 text-xs font-semibold flex items-center gap-1 mt-1">⚠️ ${errorMsg}</span>`;
    }

    return isValid;
}

function idMatch(el, keyword) {
    return el.id && el.id.toLowerCase().includes(keyword);
}

function getOrCreateFeedbackEl(inputEl) {
    let parent = inputEl.parentElement;
    let feedback = parent.querySelector('.validation-feedback');
    if (!feedback) {
        feedback = document.createElement('div');
        feedback.className = 'validation-feedback';
        parent.appendChild(feedback);
    }
    return feedback;
}

// Bind live validation to all inputs in a form
function attachLiveFormValidation(formId) {
    const form = document.getElementById(formId);
    if (!form) return;

    const inputs = form.querySelectorAll('input, select, textarea');
    inputs.forEach(input => {
        input.addEventListener('blur', () => validateInput(input));
        input.addEventListener('input', () => {
            if (input.classList.contains('border-red-500')) {
                validateInput(input);
            }
        });
    });

    form.addEventListener('submit', function (e) {
        let isAllValid = true;
        inputs.forEach(input => {
            if (!validateInput(input)) {
                isAllValid = false;
            }
        });

        if (!isAllValid) {
            e.preventDefault();
            const firstInvalid = form.querySelector('.border-red-500');
            if (firstInvalid) {
                firstInvalid.focus();
                firstInvalid.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    });
}